theorem path_stays_in_closed_ancestry (graph : List Origin) (ancestry : List String)
    (closed : ClosedAncestry graph ancestry) {a b : String}
    (start : a ∈ ancestry) (path : Path graph a b) : b ∈ ancestry

theorem equivalent_trans (M : Machine Q A) {xs ys zs : List A}
    (h₁ : Equivalent M xs ys) (h₂ : Equivalent M ys zs) :
    Equivalent M xs zs

theorem equivalent_context (M : Machine Q A) {xs ys : List A}
    (h : Equivalent M xs ys) (before after : List A) :
    Equivalent M (before ++ xs ++ after) (before ++ ys ++ after)

theorem realization_preserves_cause {CauseWitness : DiptoteIdentity → Prop}
    {ConstructionWitness : Words.Analysis → Construction → Prop}
    {GovernmentWitness : Words.Analysis → Governors.Case → Prop}
    (word : LicensedDiptote CauseWitness ConstructionWitness) (context : GenitiveContext)
    (government : GovernmentWitness word.identity.word .jarr) :
    (realizeDiptote word context government).original.identity = word.identity

theorem realization_cannot_change_word_kind {CauseWitness : DiptoteIdentity → Prop}
    {ConstructionWitness : Words.Analysis → Construction → Prop}
    {GovernmentWitness : Words.Analysis → Governors.Case → Prop}
    (word : LicensedDiptote CauseWitness ConstructionWitness) (context : GenitiveContext)
    (government : GovernmentWitness word.identity.word .jarr) :
    (realizeDiptote word context government).original.identity.word.kind = .noun

theorem evaluated_reading_sound {r : Request} {f : Frame}
    (h : (evaluate r).reading = some f) :
    r.modeAllowed = true ∧ SourceGrammar r.text f

theorem verified_binding {expected : Request} {claimed : Result}
    (h : verify expected claimed = true) :
    claimed = evaluate expected ∧ claimed.request = expected

theorem verified_reading_sound {expected : Request} {claimed : Result} {f : Frame}
    (checked : verify expected claimed = true) (reading : claimed.reading = some f) :
    expected.modeAllowed = true ∧ SourceGrammar expected.text f

theorem update_subset (eval : Model → Input → Bool) (models : List Model)
    (observation : Observation Input) {model : Model}
    (member : model ∈ update eval models observation) : model ∈ models

theorem clean_rule_premises_unblocked {p : Program α} {blocked : Atom α → Bool} {r : Rule α}
    (admitted : RuleAdmitted (cleanProgram p blocked) r) :
    ∀ a ∈ r.body, blocked a = false

theorem contextualize_preserves_analysis {Witness : Analysis → Role → Case → Prop}
    (analysis : Analysis) (role : Role) (case : Case) (witness : Witness analysis role case) :
    (contextualize analysis role case witness).analysis = analysis

theorem contextualize_preserves_occurrence {Witness : Analysis → Role → Case → Prop}
    (analysis : Analysis) (role : Role) (case : Case) (witness : Witness analysis role case) :
    (contextualize analysis role case witness).analysis.occurrence = analysis.occurrence
